{
  "title": "客栈疑云",
  "scene": "你走进一家看似普通的客栈，但气氛却显得有些异常。角落里一个披着斗篷的老人正盯着你，似乎在等待什么。吧台边的老板娘一边擦着酒杯，一边低声和伙计交谈，不时望向老人的方向。突然，门外一阵急促的脚步声，一个年轻侠士闯了进来，神色慌张地询问是否有一名老者在此。老板娘立即脸色一变，而老人则不动声色。年轻人见状，向你投来求助的目光。",
  "goal": "帮助年轻人找到老人，解开江湖谜团",
  "clue": "老板娘的紧张表情和伙计的耳语",
  "choices": [
    {
      "id": "A",
      "text": "告诉年轻人老人的位置",
      "outcome": "年轻人感激地向老人走去，但老板娘突然大喝一声，警告年轻人小心有诈。年轻人停下脚步，警惕地环顾四周。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "上前问老板娘情况",
      "outcome": "老板娘犹豫了一下，低声告诉你，老人是江湖中出了名的骗子，年轻人可能有危险。你建议年轻人小心行事。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "装作没看到年轻人",
      "outcome": "年轻人失望地离开了客栈，但你感到有些不安。门关上的那一刻，老人微微一笑，似乎你的选择正中他下怀。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
